 "lang:Python:Number Guessing & Quiz CLI": {
  "lang": "python",
  "code": "import random\n\n\ndef guessing_game():\n    secret = random.randint(1, 50)\n    tries = 0\n    print(\"I am thinking of a number between 1 and 50\")\n    while True:\n        guess = int(input(\"Your guess: \"))\n        tries += 1\n        if guess < secret:\n            print(\"Too low\")\n        elif guess > secret:\n            print(\"Too high\")\n        else:\n            print(f\"Correct! You took {tries} tries\")\n            break\n\n\ndef quiz():\n    questions = {\"Capital of India?\": \"delhi\", \"2 + 2 * 3 = ?\": \"8\", \"Python is a ___ language\": \"programming\"}\n    score = 0\n    for question, answer in questions.items():\n        if input(question + \" \").strip().lower() == answer:\n            score += 1\n    print(f\"Score: {score}/{len(questions)}\")\n\n\nif __name__ == \"__main__\":\n    guessing_game()\n    quiz()\n"
 },
 "lang:Python:Expense Tracker": {
  "lang": "python",
  "code": "import csv\nfrom datetime import date\n\nFILE = \"expenses.csv\"\n\n\ndef add_expense(amount, category, note=\"\"):\n    with open(FILE, \"a\", newline=\"\") as f:\n        csv.writer(f).writerow([date.today().isoformat(), amount, category, note])\n\n\ndef totals_by_category():\n    totals = {}\n    try:\n        with open(FILE) as f:\n            for day, amount, category, note in csv.reader(f):\n                totals[category] = totals.get(category, 0) + float(amount)\n    except FileNotFoundError:\n        pass\n    return totals\n\n\nif __name__ == \"__main__\":\n    add_expense(250, \"food\", \"lunch\")\n    add_expense(1200, \"books\")\n    for category, total in totals_by_category().items():\n        print(category, total)\n"
 },
 "lang:Python:Weather CLI with API": {
  "lang": "python",
  "code": "import requests\n\nCITIES = {\"Bhopal\": (23.26, 77.41), \"Delhi\": (28.61, 77.21), \"Mumbai\": (19.08, 72.88)}\n\n\ndef get_weather(lat, lon):\n    # open-meteo is free and needs no API key\n    url = \"https://api.open-meteo.com/v1/forecast\"\n    params = {\"latitude\": lat, \"longitude\": lon, \"current_weather\": True}\n    response = requests.get(url, params=params, timeout=10)\n    response.raise_for_status()\n    return response.json()[\"current_weather\"]\n\n\nif __name__ == \"__main__\":\n    name = input(\"City (Bhopal/Delhi/Mumbai): \").title()\n    if name in CITIES:\n        weather = get_weather(*CITIES[name])\n        print(f\"{name}: {weather['temperature']} C, wind {weather['windspeed']} km/h\")\n    else:\n        print(\"City not in the list\")\n"
 },
 "lang:Python:Flask Blog with Login": {
  "lang": "python",
  "code": "# pip install flask\nimport sqlite3\n\nfrom flask import Flask, jsonify, request, session\nfrom werkzeug.security import check_password_hash, generate_password_hash\n\napp = Flask(__name__)\napp.secret_key = \"change-this-secret\"\n\n\ndef db():\n    conn = sqlite3.connect(\"blog.db\")\n    conn.row_factory = sqlite3.Row\n    return conn\n\n\nwith db() as conn:\n    conn.execute(\"CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT UNIQUE, password TEXT)\")\n    conn.execute(\"CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY, user_id INTEGER, title TEXT, body TEXT)\")\n\n\n@app.post(\"/signup\")\ndef signup():\n    data = request.get_json()\n    with db() as conn:\n        conn.execute(\"INSERT INTO users (name, password) VALUES (?, ?)\",\n                     (data[\"name\"], generate_password_hash(data[\"password\"])))\n    return jsonify(ok=True), 201\n\n\n@app.post(\"/login\")\ndef login():\n    data = request.get_json()\n    user = db().execute(\"SELECT * FROM users WHERE name = ?\", (data[\"name\"],)).fetchone()\n    if user and check_password_hash(user[\"password\"], data[\"password\"]):\n        session[\"user_id\"] = user[\"id\"]\n        return jsonify(ok=True)\n    return jsonify(error=\"wrong details\"), 401\n\n\n@app.post(\"/posts\")\ndef new_post():\n    if \"user_id\" not in session:\n        return jsonify(error=\"login first\"), 401\n    data = request.get_json()\n    with db() as conn:\n        conn.execute(\"INSERT INTO posts (user_id, title, body) VALUES (?, ?, ?)\",\n                     (session[\"user_id\"], data[\"title\"], data[\"body\"]))\n    return jsonify(ok=True), 201\n\n\n@app.get(\"/posts\")\ndef posts():\n    return jsonify([dict(row) for row in db().execute(\"SELECT * FROM posts ORDER BY id DESC\")])\n\n\nif __name__ == \"__main__\":\n    app.run(debug=True)\n"
 },
