 "rec:flask-notes": {
  "lang": "python",
  "code": "# pip install flask\nfrom flask import Flask, jsonify, request\n\napp = Flask(__name__)\nnotes = []          # later: replace this list with a SQLite table\nnext_id = 1\n\n\n@app.get(\"/notes\")\ndef list_notes():\n    return jsonify(notes)\n\n\n@app.post(\"/notes\")\ndef create_note():\n    global next_id\n    data = request.get_json()\n    if not data or not data.get(\"title\"):\n        return jsonify(error=\"title is required\"), 400\n    note = {\"id\": next_id, \"title\": data[\"title\"], \"body\": data.get(\"body\", \"\")}\n    next_id += 1\n    notes.append(note)\n    return jsonify(note), 201\n\n\n@app.put(\"/notes/<int:note_id>\")\ndef update_note(note_id):\n    for note in notes:\n        if note[\"id\"] == note_id:\n            note.update(request.get_json())\n            return jsonify(note)\n    return jsonify(error=\"not found\"), 404\n\n\n@app.delete(\"/notes/<int:note_id>\")\ndef delete_note(note_id):\n    global notes\n    notes = [n for n in notes if n[\"id\"] != note_id]\n    return \"\", 204\n\n\nif __name__ == \"__main__\":\n    app.run(debug=True)\n"
 },
 "rec:student-mgmt": {
  "lang": "python",
  "code": "# pip install flask\nimport sqlite3\n\nfrom flask import Flask, jsonify, request\n\napp = Flask(__name__)\nDB = \"students.db\"\n\n\ndef query(sql, params=(), one=False, commit=False):\n    conn = sqlite3.connect(DB)\n    conn.row_factory = sqlite3.Row\n    cur = conn.execute(sql, params)\n    if commit:\n        conn.commit()\n    rows = cur.fetchall()\n    conn.close()\n    return (rows[0] if rows else None) if one else rows\n\n\nquery(\"CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY, name TEXT NOT NULL, course TEXT, marks INTEGER)\", commit=True)\n\n\n@app.get(\"/students\")\ndef all_students():\n    return jsonify([dict(r) for r in query(\"SELECT * FROM students\")])\n\n\n@app.post(\"/students\")\ndef add_student():\n    d = request.get_json()\n    query(\"INSERT INTO students (name, course, marks) VALUES (?, ?, ?)\", (d[\"name\"], d.get(\"course\"), d.get(\"marks\", 0)), commit=True)\n    return jsonify(ok=True), 201\n\n\n@app.put(\"/students/<int:sid>\")\ndef update_student(sid):\n    d = request.get_json()\n    query(\"UPDATE students SET name = ?, course = ?, marks = ? WHERE id = ?\", (d[\"name\"], d.get(\"course\"), d.get(\"marks\", 0), sid), commit=True)\n    return jsonify(ok=True)\n\n\n@app.delete(\"/students/<int:sid>\")\ndef delete_student(sid):\n    query(\"DELETE FROM students WHERE id = ?\", (sid,), commit=True)\n    return \"\", 204\n\n\nif __name__ == \"__main__\":\n    app.run(debug=True)\n"
 },
 "rec:url-shortener": {
  "lang": "python",
  "code": "# pip install flask\nimport random\nimport sqlite3\nimport string\n\nfrom flask import Flask, jsonify, redirect, request\n\napp = Flask(__name__)\nDB = \"urls.db\"\n\n\ndef db():\n    conn = sqlite3.connect(DB)\n    conn.row_factory = sqlite3.Row\n    return conn\n\n\nwith db() as conn:\n    conn.execute(\"CREATE TABLE IF NOT EXISTS urls (code TEXT PRIMARY KEY, target TEXT NOT NULL, clicks INTEGER DEFAULT 0)\")\n\n\ndef make_code(length=6):\n    return \"\".join(random.choices(string.ascii_letters + string.digits, k=length))\n\n\n@app.post(\"/shorten\")\ndef shorten():\n    target = (request.get_json() or {}).get(\"url\", \"\")\n    if not target.startswith((\"http://\", \"https://\")):\n        return jsonify(error=\"send a full url starting with http:// or https://\"), 400\n    code = make_code()\n    with db() as conn:\n        conn.execute(\"INSERT INTO urls (code, target) VALUES (?, ?)\", (code, target))\n    return jsonify(short=request.host_url + code), 201\n\n\n@app.get(\"/<code>\")\ndef go(code):\n    with db() as conn:\n        row = conn.execute(\"SELECT target FROM urls WHERE code = ?\", (code,)).fetchone()\n        if not row:\n            return jsonify(error=\"unknown code\"), 404\n        conn.execute(\"UPDATE urls SET clicks = clicks + 1 WHERE code = ?\", (code,))\n    return redirect(row[\"target\"])\n\n\nif __name__ == \"__main__\":\n    app.run(debug=True)\n\n# Next: add a Dockerfile (FROM python:3.12-slim, pip install flask, CMD python app.py)\n"
 },
 "rec:dsa-toolkit": {
  "lang": "python",
  "code": "import unittest\n\n\nclass Stack:\n    def __init__(self):\n        self.items = []\n\n    def push(self, value):\n        self.items.append(value)\n\n    def pop(self):\n        if not self.items:\n            raise IndexError(\"stack is empty\")\n        return self.items.pop()\n\n    def peek(self):\n        return self.items[-1] if self.items else None\n\n\nclass Queue:\n    def __init__(self):\n        self.items = []\n\n    def enqueue(self, value):\n        self.items.append(value)\n\n    def dequeue(self):\n        if not self.items:\n            raise IndexError(\"queue is empty\")\n        return self.items.pop(0)\n\n\ndef binary_search(sorted_list, target):\n    low, high = 0, len(sorted_list) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if sorted_list[mid] == target:\n            return mid\n        if sorted_list[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n\n\nclass ToolkitTests(unittest.TestCase):\n    def test_stack(self):\n        s = Stack()\n        s.push(1)\n        s.push(2)\n        self.assertEqual(s.pop(), 2)\n\n    def test_queue(self):\n        q = Queue()\n        q.enqueue(\"a\")\n        q.enqueue(\"b\")\n        self.assertEqual(q.dequeue(), \"a\")\n\n    def test_binary_search(self):\n        self.assertEqual(binary_search([1, 3, 5, 7, 9], 7), 3)\n        self.assertEqual(binary_search([1, 3, 5], 4), -1)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 },
 "rec:library-oop": {
  "lang": "python",
  "code": "class Book:\n    def __init__(self, book_id, title, author):\n        self.book_id = book_id\n        self.title = title\n        self.author = author\n        self.is_issued = False\n\n\nclass Member:\n    def __init__(self, name):\n        self.name = name\n        self.borrowed = []\n\n\nclass Library:\n    MAX_BOOKS = 2\n\n    def __init__(self):\n        self.books = {}\n\n    def add_book(self, book):\n        self.books[book.book_id] = book\n\n    def issue(self, book_id, member):\n        book = self.books.get(book_id)\n        if book is None:\n            return \"No such book\"\n        if book.is_issued:\n            return \"Book already issued\"\n        if len(member.borrowed) >= self.MAX_BOOKS:\n            return \"Limit reached\"\n        book.is_issued = True\n        member.borrowed.append(book)\n        return f\"{book.title} issued to {member.name}\"\n\n    def give_back(self, book_id, member):\n        for book in member.borrowed:\n            if book.book_id == book_id:\n                book.is_issued = False\n                member.borrowed.remove(book)\n                return \"Returned\"\n        return \"This member does not have that book\"\n\n\nif __name__ == \"__main__\":\n    lib = Library()\n    lib.add_book(Book(1, \"Python Basics\", \"A. Sharma\"))\n    asha = Member(\"Asha\")\n    print(lib.issue(1, asha))\n    print(lib.issue(1, asha))\n    print(lib.give_back(1, asha))\n"
 },
