  "code": "# Only scan machines you own or have written permission to test (use localhost for practice).\nimport socket\n\n\ndef scan(host, ports, timeout=0.5):\n    open_ports = []\n    for port in ports:\n        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\n            s.settimeout(timeout)\n            if s.connect_ex((host, port)) == 0:\n                open_ports.append(port)\n    return open_ports\n\n\nif __name__ == \"__main__\":\n    target = \"127.0.0.1\"\n    found = scan(target, [21, 22, 80, 443, 3306, 5000, 8080])\n    print(f\"Open ports on {target}:\", found or \"none\")\n"
