 "rec:crypto-vault": {
  "lang": "python",
  "code": "import hashlib\nimport hmac\nimport os\n\n\ndef hash_password(password):\n    salt = os.urandom(16)\n    digest = hashlib.pbkdf2_hmac(\"sha256\", password.encode(), salt, 200_000)\n    return salt.hex() + \":\" + digest.hex()\n\n\ndef check_password(password, stored):\n    salt_hex, digest_hex = stored.split(\":\")\n    digest = hashlib.pbkdf2_hmac(\"sha256\", password.encode(), bytes.fromhex(salt_hex), 200_000)\n    return hmac.compare_digest(digest.hex(), digest_hex)\n\n\nif __name__ == \"__main__\":\n    stored = hash_password(\"MySecret@123\")\n    print(\"Stored value:\", stored[:40], \"...\")\n    print(\"Right password:\", check_password(\"MySecret@123\", stored))\n    print(\"Wrong password:\", check_password(\"guess\", stored))\n    # Same password hashed twice gives different results because of the random salt.\n"
 },
