 "rec:react-ecom": {
  "lang": "jsx",
  "code": "import { useState } from \"react\";\n\nconst PRODUCTS = [\n  { id: 1, name: \"Notebook\", price: 80 },\n  { id: 2, name: \"Pen pack\", price: 40 },\n  { id: 3, name: \"Backpack\", price: 650 },\n];\n\nexport default function App() {\n  const [cart, setCart] = useState({});           // { productId: quantity }\n\n  const add = (id) => setCart({ ...cart, [id]: (cart[id] || 0) + 1 });\n  const remove = (id) => {\n    const next = { ...cart };\n    if (next[id] > 1) next[id] -= 1;\n    else delete next[id];\n    setCart(next);\n  };\n  const total = PRODUCTS.reduce((sum, p) => sum + p.price * (cart[p.id] || 0), 0);\n\n  return (\n    <div>\n      <h1>Shop</h1>\n      {PRODUCTS.map((p) => (\n        <div key={p.id}>\n          {p.name} - Rs {p.price} <button onClick={() => add(p.id)}>Add</button>\n        </div>\n      ))}\n      <h2>Cart</h2>\n      {PRODUCTS.filter((p) => cart[p.id]).map((p) => (\n        <div key={p.id}>\n          {p.name} x {cart[p.id]} <button onClick={() => remove(p.id)}>-</button>\n        </div>\n      ))}\n      <h3>Total: Rs {total}</h3>\n    </div>\n  );\n}\n"
 },
