 "rec:ts-kanban": {
  "lang": "tsx",
  "code": "import { useState } from \"react\";\n\ntype Status = \"todo\" | \"doing\" | \"done\";\ninterface Card { id: number; title: string; status: Status; }\n\nconst COLUMNS: Status[] = [\"todo\", \"doing\", \"done\"];\n\nexport default function App() {\n  const [cards, setCards] = useState<Card[]>([{ id: 1, title: \"Learn TypeScript\", status: \"todo\" }]);\n  const [title, setTitle] = useState(\"\");\n\n  const addCard = () => {\n    if (!title.trim()) return;\n    setCards([...cards, { id: Date.now(), title, status: \"todo\" }]);\n    setTitle(\"\");\n  };\n  const move = (id: number, direction: 1 | -1) =>\n    setCards(cards.map((c) => {\n      if (c.id !== id) return c;\n      const index = COLUMNS.indexOf(c.status) + direction;\n      return index < 0 || index >= COLUMNS.length ? c : { ...c, status: COLUMNS[index] };\n    }));\n\n  return (\n    <div>\n      <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder=\"New card\" />\n      <button onClick={addCard}>Add</button>\n      <div style={{ display: \"flex\", gap: 20 }}>\n        {COLUMNS.map((col) => (\n          <div key={col}>\n            <h3>{col}</h3>\n            {cards.filter((c) => c.status === col).map((c) => (\n              <div key={c.id}>\n                <button onClick={() => move(c.id, -1)}>&lt;</button>\n                {c.title}\n                <button onClick={() => move(c.id, 1)}>&gt;</button>\n              </div>\n            ))}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n"
 },
