  "code": "// Create the project at start.spring.io: Spring Web, Spring Data JPA, H2 Database.\n// File 1: Employee.java\nimport jakarta.persistence.*;\n\n@Entity\npublic class Employee {\n    @Id\n    @GeneratedValue(strategy = GenerationType.IDENTITY)\n    private Long id;\n    private String name;\n    private String department;\n    private double salary;\n\n    public Long getId() { return id; }\n    public String getName() { return name; }\n    public void setName(String name) { this.name = name; }\n    public String getDepartment() { return department; }\n    public void setDepartment(String department) { this.department = department; }\n    public double getSalary() { return salary; }\n    public void setSalary(double salary) { this.salary = salary; }\n}\n\n// File 2: EmployeeRepository.java\nimport org.springframework.data.jpa.repository.JpaRepository;\n\npublic interface EmployeeRepository extends JpaRepository<Employee, Long> { }\n\n// File 3: EmployeeController.java\nimport java.util.List;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping(\"/employees\")\npublic class EmployeeController {\n    private final EmployeeRepository repo;\n\n    public EmployeeController(EmployeeRepository repo) { this.repo = repo; }\n\n    @GetMapping\n    public List<Employee> all() { return repo.findAll(); }\n\n    @PostMapping\n    public Employee create(@RequestBody Employee e) { return repo.save(e); }\n\n    @GetMapping(\"/{id}\")\n    public ResponseEntity<Employee> one(@PathVariable Long id) {\n        return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());\n    }\n\n    @DeleteMapping(\"/{id}\")\n    public void delete(@PathVariable Long id) { repo.deleteById(id); }\n}\n"
