  "code": "// build.gradle: retrofit, converter-gson and the INTERNET permission in AndroidManifest.xml\n// (use a free key from newsapi.org or gnews.io)\n\n// ---- Models.kt\ndata class NewsResponse(val articles: List<Article>)\ndata class Article(val title: String, val description: String?, val url: String)\n\n// ---- NewsApi.kt\nimport retrofit2.Retrofit\nimport retrofit2.converter.gson.GsonConverterFactory\nimport retrofit2.http.GET\nimport retrofit2.http.Query\n\ninterface NewsApi {\n    @GET(\"v2/top-headlines\")\n    suspend fun headlines(@Query(\"country\") country: String, @Query(\"apiKey\") key: String): NewsResponse\n}\n\nval newsApi: NewsApi = Retrofit.Builder()\n    .baseUrl(\"https://newsapi.org/\")\n    .addConverterFactory(GsonConverterFactory.create())\n    .build()\n    .create(NewsApi::class.java)\n\n// ---- NewsViewModel.kt\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.launch\n\nclass NewsViewModel : ViewModel() {\n    val articles = MutableStateFlow<List<Article>>(emptyList())\n    val error = MutableStateFlow<String?>(null)\n\n    fun load() = viewModelScope.launch {\n        try {\n            articles.value = newsApi.headlines(\"in\", \"YOUR_API_KEY\").articles\n        } catch (e: Exception) {\n            error.value = \"Could not load news\"\n        }\n    }\n}\n"
